42:   /** Build the one product-level Knowledge Graph used by AI exports. */
43:   private getGraphData(): GraphData {
44:     const snapshot = this.knowledgeGraphService.getSnapshot();
45:     const observations: Array<{ entityId: string; entityName: string; content: string }> = [];
46:     for (const entity of snapshot.entities) {
47:       const entityObservations = this.knowledgeGraphService.getObservations(entity.id);
48:       for (const obs of entityObservations) {
49:         observations.push({
50:           entityId: entity.id,
51:           entityName: entity.name,
52:           content: obs.content
53:         });
54:       }
55:     }
56: 
57:     return {
58:       entities: snapshot.entities,
59:       relations: snapshot.relations,
60:       observations,
61:       sourceType: 'knowledge',
62:     };
63:   }
