65:   /**
66:    * 获取文件相对于工作区的路径
67:    */
68:   private getRelativePath(document: vscode.TextDocument): string | null {
69:     const workspaceFolder = vscode.workspace.getWorkspaceFolder(document.uri);
70:     if (!workspaceFolder) {
71:       return null;
72:     }
73:     
74:     // 使用 path.relative 计算相对路径，确保返回字符串
75:     const absolutePath = document.uri.fsPath;
76:     const workspacePath = workspaceFolder.uri.fsPath;
77:     const relativePath = path.relative(workspacePath, absolutePath);
78:     
79:     // 统一使用正斜杠（跨平台兼容）
80:     return relativePath.replace(/\\/g, '/');
81:   }
