83:   /**
84:    * 从选中的代码创建实体
85:    */
86:   public async createEntityFromSelection(): Promise<void> {
87:     const editor = vscode.window.activeTextEditor;
88:     if (!editor) {
89:       vscode.window.showWarningMessage(t().common.noActiveEditor);
90:       return;
91:     }
92: 
93:     const selection = editor.selection;
94:     const workspaceFolder = vscode.workspace.getWorkspaceFolder(editor.document.uri);
95:     if (!workspaceFolder) {
96:       vscode.window.showWarningMessage(t().common.fileNotInWorkspace);
97:       return;
98:     }
99: 
100:     // 获取选中的文本
101:     const selectedText = editor.document.getText(selection);
102:     const defaultName = selectedText.trim().split(/\s+/)[0] || 'New Entity';
103: 
104:     // 输入实体名称
105:     const name = await vscode.window.showInputBox({
106:       prompt: t().commands.createEntity.prompt,
107:       value: defaultName,
108:       validateInput: (value) => {
109:         return value.trim() ? null : t().commands.createEntity.validateEmpty;
110:       },
111:     });
112: 
113:     if (!name) {
114:       return;
115:     }
116: 
117:     // 选择实体类型
118:     const typeOptions: vscode.QuickPickItem[] = Object.entries(t().entityTypes).map(([, value]) => ({
119:       label: value.label,
120:       description: value.description
121:     }));
122: 
123:     const selectedType = await vscode.window.showQuickPick(typeOptions, {
124:       placeHolder: t().commands.createEntity.placeholder,
125:     });
126: 
127:     if (!selectedType) {
128:       return;
129:     }
130: 
131:     // 输入描述（可选）
132:     const description = await vscode.window.showInputBox({
133:       prompt: t().common.description,
134:     });
135: 
136:     // 创建实体
137:     try {
138:       const relativePath = this.getRelativePath(editor.document);
139:       if (!relativePath) {
140:         vscode.window.showWarningMessage(t().common.fileNotInWorkspace);
141:         return;
142:       }
143: 
144:       const entity = this.entityService.createEntity(
145:         name,
146:         selectedType.label as EntityType,
147:         {
148:           filePath: relativePath,
149:           startLine: selection.start.line + 1,
150:           endLine: selection.end.line + 1,
151:         },
152:         description
153:       );
154: 
155:       vscode.window.showInformationMessage(
156:         t().commands.createEntity.success(entity.name)
157:       );
158:     } catch (error) {
159:       vscode.window.showErrorMessage(
160:         t().commands.createEntity.error(String(error))
161:       );
162:     }
163:   }
