417:             if (!graph) {
418:                 throw new Error('Structural graph service is unavailable.');
419:             }
420:             const selectedFiles = new Set(Array.isArray(files) ? files : []);
421:             const matches = (entity: StructuralGraphEntity) => {
422:                 if (selectedFiles.size > 0) {
423:                     return selectedFiles.has(entity.filePath);
424:                 }
425:                 if (level === 'file') {
